import type { Rect, SceneNode } from "../shared/contracts";
import { borderWidth, uniformBorder } from "./borders";

/** Largest difference, in pixels, between the browser's box and the model. */
export const FLEX_TOLERANCE = 1;

export type FlexJustify = "start" | "center" | "end" | "space-between" | "space-around" | "space-evenly";
export type FlexAlign = "start" | "center" | "end";

export interface FlexPlan {
  dir: "row" | "column";
  gap: number;
  /** Top, right, bottom, left, measured from the board edge: CSS padding plus border. */
  padding: [number, number, number, number];
  justify: FlexJustify;
  align: FlexAlign;
  /** In-flow children, in source order. */
  flow: SceneNode[];
  /** Positioned children that sit outside the flow, topmost first. */
  absolute: SceneNode[];
}

export type FlexDecision = { plan: FlexPlan } | { reason: string };

const JUSTIFY: Record<string, FlexJustify> = {
  normal: "start", "flex-start": "start", start: "start", center: "center", "flex-end": "end", end: "end",
  "space-between": "space-between", "space-around": "space-around", "space-evenly": "space-evenly"
};
// The browser's default (normal/stretch) already gives each child its stretched
// size in the snapshot, so top-aligning fixed-size children reproduces it.
const ALIGN: Record<string, FlexAlign> = {
  normal: "start", stretch: "start", "flex-start": "start", start: "start", "self-start": "start",
  center: "center", "flex-end": "end", end: "end", "self-end": "end"
};

const positioned = (node: SceneNode): boolean => Boolean(node.layout.positioned || node.layout.absolute);
const rankOf = (node: SceneNode): string => node.zIndex < 0 ? `n${node.zIndex}` : node.zIndex > 0 ? `p${node.zIndex}` : positioned(node) ? "positioned" : "flow";

/**
 * Predict where a flex container of the supported subset places fixed-size
 * children. Positions are relative to the container's top-left corner. The same
 * model checks the browser snapshot before conversion and the host layout after.
 */
export function predictFlex(plan: Pick<FlexPlan, "dir" | "gap" | "padding" | "justify" | "align">, size: { width: number; height: number }, children: { width: number; height: number }[]): Rect[] {
  const [top, right, bottom, left] = plan.padding;
  const row = plan.dir === "row";
  const innerMain = (row ? size.width - left - right : size.height - top - bottom);
  const innerCross = (row ? size.height - top - bottom : size.width - left - right);
  const mains = children.map((child) => row ? child.width : child.height);
  const free = innerMain - mains.reduce((sum, value) => sum + value, 0) - plan.gap * Math.max(0, children.length - 1);
  let offset = 0;
  let spacing = plan.gap;
  const count = children.length;
  if (plan.justify === "center") offset = free / 2;
  else if (plan.justify === "end") offset = free;
  else if (plan.justify === "space-between" && count > 1) spacing += free / (count - 1);
  else if (plan.justify === "space-around") { offset = free / count / 2; spacing += free / count; }
  else if (plan.justify === "space-evenly") { offset = free / (count + 1); spacing += free / (count + 1); }
  let cursor = (row ? left : top) + offset;
  return children.map((child, index) => {
    const main = mains[index];
    const cross = row ? child.height : child.width;
    const crossOffset = plan.align === "center" ? (innerCross - cross) / 2 : plan.align === "end" ? innerCross - cross : 0;
    const crossStart = (row ? top : left) + crossOffset;
    const rect = row
      ? { x: cursor, y: crossStart, width: child.width, height: child.height }
      : { x: crossStart, y: cursor, width: child.width, height: child.height };
    cursor += main + spacing;
    return rect;
  });
}

/** True when every rect matches its prediction within the tolerance. */
export function matchesPrediction(actual: Rect[], expected: Rect[], tolerance = FLEX_TOLERANCE): boolean {
  return actual.length === expected.length && actual.every((rect, index) => Math.abs(rect.x - expected[index].x) <= tolerance && Math.abs(rect.y - expected[index].y) <= tolerance);
}

/**
 * Decide whether a container's captured layout maps to a native Penpot flex
 * layout without changing its initial appearance. `children` are the
 * container's scene children in source order.
 */
export function planFlex(container: SceneNode, children: SceneNode[]): FlexDecision {
  const layout = container.layout;
  if (container.kind !== "container" || layout.kind !== "flex") return { reason: "It is not a flex container." };
  if (container.rotation) return { reason: "The container is rotated." };
  if (layout.direction !== "row" && layout.direction !== "column") return { reason: `flex-direction ${layout.direction ?? "unknown"} is not supported.` };
  if (layout.wrap === "wrap") return { reason: "Wrapping flex containers are not supported." };
  const justify = JUSTIFY[layout.justifyContent ?? "normal"];
  if (!justify) return { reason: `justify-content ${layout.justifyContent} is not supported.` };
  const align = ALIGN[layout.alignItems ?? "normal"];
  if (!align) return { reason: `align-items ${layout.alignItems} is not supported.` };
  if (container.paint.borders && !uniformBorder(container.paint)) return { reason: "Per-side borders are drawn as separate paths." };
  if (children.some((child) => child.rotation)) return { reason: "A child is rotated." };
  const absolute = children.filter((child) => child.layout.absolute);
  if (absolute.some((child) => child.zIndex < 0)) return { reason: "An absolutely positioned child paints behind the container's content." };
  const flow = children.filter((child) => !child.layout.absolute);
  if (!flow.length) return { reason: "It has no in-flow children." };
  // Penpot lays children out in layer order, so the browser's paint order must
  // match source order among them; a z-index or positioned sibling would not.
  if (new Set(flow.map(rankOf)).size > 1) return { reason: "In-flow children differ in stacking, so their paint order is not their source order." };
  if (absolute.length && rankOf(flow[0]) !== "flow") return { reason: "Positioned or stacked in-flow children can paint above or below the absolutely positioned ones." };
  const border = borderWidth(container.paint, "top");
  const [top, right, bottom, left] = layout.padding ?? [0, 0, 0, 0];
  const gap = (layout.direction === "row" ? layout.columnGap : layout.rowGap) ?? 0;
  const plan: FlexPlan = {
    dir: layout.direction, gap, padding: [top + border, right + border, bottom + border, left + border], justify, align, flow,
    absolute: absolute.slice().reverse().sort((a, b) => b.zIndex - a.zIndex)
  };
  const free = (layout.direction === "row" ? container.rect.width - plan.padding[1] - plan.padding[3] : container.rect.height - plan.padding[0] - plan.padding[2])
    - flow.reduce((sum, child) => sum + (layout.direction === "row" ? child.rect.width : child.rect.height), 0) - gap * (flow.length - 1);
  if (justify !== "start" && free < -FLEX_TOLERANCE) return { reason: "The children overflow the container, which the native layout positions differently." };
  const expected = predictFlex(plan, container.rect, flow.map((child) => child.rect));
  const actual = flow.map((child) => ({ x: child.rect.x - container.rect.x, y: child.rect.y - container.rect.y, width: child.rect.width, height: child.rect.height }));
  if (!matchesPrediction(actual, expected)) return { reason: "The captured child positions do not match the supported flex model (margins, flex-grow, order, or auto margins)." };
  return { plan };
}
import type { Board, Shape } from "@penpot/plugin-types";
import type { Diagnostic, SceneNode } from "../shared/contracts";
import { FLEX_TOLERANCE, matchesPrediction, predictFlex, type FlexPlan } from "./flexLayout";

/** A board already holding its children at their captured positions. */
export interface NativeFlexEntry {
  node: SceneNode;
  plan: FlexPlan;
  board: Board;
  flow: (Shape | undefined)[];
  absolute: (Shape | undefined)[];
}

export interface NativeLayoutHooks {
  wait: (milliseconds: number) => Promise<void>;
  markDirty: () => void;
  diagnostic: (diagnostic: Diagnostic) => void;
  viewportId: string;
}

export interface NativeLayoutResult {
  converted: number;
  reverted: number;
}

// The host applies a layout asynchronously: positions were still the captured
// ones immediately afterwards and settled within 100 ms in live passes.
const SETTLE_DELAYS = [150, 250, 400];

interface Saved {
  entry: NativeFlexEntry;
  flow: Shape[];
  absolute: Shape[];
  offsets: Map<Shape, { dx: number; dy: number }>;
}

const rectOf = (shape: Shape, board: Board) => ({ x: shape.x - board.x, y: shape.y - board.y, width: shape.width, height: shape.height });

function settled(saved: Saved): boolean {
  const { entry, flow, absolute, offsets } = saved;
  const { board, plan } = entry;
  const actual = flow.map((shape) => rectOf(shape, board));
  // Predict from the sizes the host now has: text fitting may have changed
  // widths, and a native layout is expected to reflow around them.
  const expected = predictFlex(plan, { width: board.width, height: board.height }, actual);
  if (!matchesPrediction(actual, expected)) return false;
  return absolute.every((shape) => {
    const original = offsets.get(shape)!;
    return Math.abs(shape.x - board.x - original.dx) <= FLEX_TOLERANCE && Math.abs(shape.y - board.y - original.dy) <= FLEX_TOLERANCE;
  });
}

function restore(saved: Saved): void {
  const { entry, offsets } = saved;
  entry.board.flex?.remove();
  for (const shape of [...saved.flow, ...saved.absolute]) {
    const original = offsets.get(shape)!;
    shape.x = entry.board.x + original.dx;
    shape.y = entry.board.y + original.dy;
  }
}

/**
 * Turn captured containers into native Penpot flex boards, keeping only those
 * whose resulting layout reproduces the supported model. Children are first
 * piled at the board origin, so a layout that never ran is detected rather
 * than mistaken for one that matched. Entries are ordered outermost first.
 */
export async function applyNativeLayouts(entries: NativeFlexEntry[], hooks: NativeLayoutHooks): Promise<NativeLayoutResult> {
  const result: NativeLayoutResult = { converted: 0, reverted: 0 };
  const skipped: string[] = [];
  const usable: Saved[] = [];
  for (const entry of entries) {
    const flow = entry.flow.filter((shape): shape is Shape => Boolean(shape));
    const absolute = entry.absolute.filter((shape): shape is Shape => Boolean(shape));
    const complete = flow.length === entry.flow.length && absolute.length === entry.absolute.length;
    if (!complete || [...flow, ...absolute].some((shape) => shape.parent?.id !== entry.board.id)) {
      skipped.push(entry.node.source);
      continue;
    }
    const offsets = new Map<Shape, { dx: number; dy: number }>();
    for (const shape of [...flow, ...absolute]) offsets.set(shape, { dx: shape.x - entry.board.x, dy: shape.y - entry.board.y });
    usable.push({ entry, flow, absolute, offsets });
  }
  for (const { entry, flow, absolute, offsets } of usable) {
    const { board, plan } = entry;
    for (const shape of flow) { shape.x = board.x; shape.y = board.y; }
    const layout = board.addFlexLayout();
    layout.dir = plan.dir;
    layout.wrap = "nowrap";
    layout.rowGap = plan.gap;
    layout.columnGap = plan.gap;
    [layout.topPadding, layout.rightPadding, layout.bottomPadding, layout.leftPadding] = plan.padding;
    layout.justifyContent = plan.justify;
    layout.alignItems = plan.align;
    for (const shape of absolute) {
      if (shape.layoutChild) shape.layoutChild.absolute = true;
      const original = offsets.get(shape)!;
      shape.x = board.x + original.dx;
      shape.y = board.y + original.dy;
    }
    hooks.markDirty();
  }
  let pending = usable;
  for (const delay of SETTLE_DELAYS) {
    if (!pending.length) break;
    await hooks.wait(delay);
    pending = pending.filter((saved) => !settled(saved));
  }
  const failed = new Set(pending);
  // Undo outer layouts first: restoring an inner board's children is relative
  // to that board, which must already be back where it started.
  for (const saved of usable) {
    if (!failed.has(saved)) continue;
    restore(saved);
    result.reverted += 1;
    skipped.push(saved.entry.node.source);
  }
  for (const saved of usable) {
    if (failed.has(saved)) continue;
    saved.entry.board.setPluginData("native-layout", "flex");
    result.converted += 1;
  }
  if (result.reverted || skipped.length) {
    const count = skipped.length;
    hooks.diagnostic({
      severity: "warning",
      code: "NATIVE_LAYOUT_REVERTED",
      message: `${count} flex container${count === 1 ? "" : "s"} could not be reproduced by Penpot's layout and kept fixed geometry` + (count > 1 ? `, including ${skipped.slice(0, 3).join(", ")}.` : "."),
      viewportId: hooks.viewportId,
      source: skipped[0]
    });
  }
  if (result.reverted) hooks.markDirty();
  return result;
}
# Native flex layouts (opt-in)

By default every board the importer creates is a fixed snapshot of the viewport:
each layer sits at the position the browser measured, so the result matches the
page but does not respond when you edit it. **Native flex layouts** is an opt-in
setting (Advanced capture, off by default) that turns simple flex containers
into Penpot flex boards, so resizing the board, resizing a child, or adding a
layer reflows its children. Anything the conversion cannot reproduce exactly
stays a fixed snapshot. Nothing about the default import changes.

Status: unit, fixture, and importer regressions are checked in, and a live
Penpot pass covers geometry at all three viewports, resizing and editing,
undo/redo, and a saved reload; see [Verification](#verification).

## How a container is chosen

The conversion is decided in two stages, both against the same small model
(`predictFlex` in `src/importer/flexLayout.ts`) of how a flex container places
fixed-size children.

1. **Before import (browser snapshot).** A container qualifies only when the
   model, fed the browser's own child sizes, reproduces the browser's child
   positions within 1 px. Margins, `flex-grow`, `order`, auto margins, and
   anything else the model cannot express fail this check on their own, so
   unsupported CSS cannot silently shift layers.
2. **After import (host check).** Penpot applies a layout asynchronously, and in
   live passes the first layout on a freshly opened page did not run at all.
   The importer therefore piles the children at the board origin before adding
   the layout, waits for the host to settle, and requires the host's positions
   to match the model fed the host's current sizes. A layout that never ran, or
   ran differently, is removed and the children return to their captured
   offsets, with a `NATIVE_LAYOUT_REVERTED` diagnostic.

Text may reflow in Penpot's substituted font, which is why the host check uses
the host's sizes rather than the browser's.

## Supported subset

| CSS | Penpot |
| --- | --- |
| `display: flex` / `inline-flex`, `flex-direction: row` or `column` | A board with a flex layout of the same direction. |
| `gap` | Row and column gap. |
| `padding` (plus a uniform border) | Board padding. A uniform border is a native inside stroke and does not move children, so its width is added to the padding. |
| `justify-content`: `flex-start`, `center`, `flex-end`, `space-between`, `space-around`, `space-evenly` | The matching justification. Centering and spacing require the children to fit. |
| `align-items`: `flex-start`, `center`, `flex-end`, and the default `stretch` | Start, center, end. Captured children already have their stretched size, so start alignment reproduces `stretch`. |
| Absolutely positioned children | Flagged as outside the flow and kept at their captured offset. They are appended first so they stay topmost. |
| Nested flex containers | Each converts on its own merits. |
| Fill, border, radius, shadow, opacity, background image | Painted by the board as for any container. |

Children keep their captured size, and the board keeps its captured size: there
is no hug, `flex-grow`, or `flex-shrink` conversion. Penpot lays children out in
the order they were appended, first appended first, whereas paint order appends
the topmost first. The flow is therefore appended in source order.

## Kept as fixed geometry

A container that does not qualify is imported exactly as before. One
`NATIVE_LAYOUT_SKIPPED` diagnostic per viewport counts the containers and groups
them by reason.

| Reason | Why |
| --- | --- |
| `flex-wrap: wrap`, `row-reverse`, `column-reverse` | Wrapping and reversed order depend on `align-content` and on how Penpot orders reversed layouts. |
| `align-items: baseline`, other justifications (`left`, `right`, and similar) | No Penpot equivalent. |
| Per-side borders | They are drawn as separate paths that would become layout children. |
| Rotated container or child | Layout positions are axis-aligned. |
| In-flow children that differ in stacking (z-index, mixed positioned and static) | Penpot orders by layer, so paint order must equal source order. |
| An absolute child behind the content, or positioned flow children with absolute siblings | The layering cannot be reproduced. |
| Centering or spacing with overflowing children | The browser and Penpot place overflow differently. |
| Margins, `order`, `flex-grow`, auto margins | The browser positions do not fit the model. |
| A stack of plain text layers | See below. |

**Text-only items do not always qualify.** The scene records a text layer's
glyph rectangle, not its element's line box, so a column of bare text lines
(a heading above a caption, for instance) differs from the model by the line
leading and falls back to fixed geometry. Text inside a box, button, or card
qualifies because the box is the flex item. Recording the line box would let
these convert too.

## Grid

Assessed, not converted. Penpot has a grid layout with typed tracks and per-child
cell placement, but the capture records only that a container is a grid and its
gaps; it does not record track templates or item placement, and there is no
verified model of how Penpot sizes auto and fractional tracks. Grid needs those
captured first, then the same model-and-verify approach used here.

## Verification

- Fixture [`flex-layouts.html`](../src/capture/fixtures/flex-layouts.html): six
  supported containers (basic, space-between, column, centered, a decorated card
  with a nested flex column, an absolute badge) and five kept fixed (wrap, row
  reverse, auto margin, `order`, baseline), with three real-Chrome references
  (every earlier screenshot and scene unchanged). The baseline runner pins the
  captured flex semantics.
- `src/importer/flexLayout.test.ts` (13 tests) covers the model, each
  justification, the border-plus-padding rule, and every rejection reason.
  `flexLayout.fixture.test.ts` runs the planner over the real browser scenes at
  all three viewports. `nativeLayout.test.ts` (7 tests) drives the host step with
  a simulated Penpot: a layout that runs, reflows around changed sizes, never
  runs, runs wrongly, absolute children, missing children, and configuration.
  `penpot.test.ts` imports the fixture with the option off (no layout requested),
  on (supported boards converted at the captured positions), and with a host
  that never applies layouts (full fallback).
- Validation: all 442 tests pass; app, API, and Worker typechecks, the
  production build, and `npm run check:dist` pass. `npm run test:importer-fixtures`
  passes 321 tests in 17 files.
- Live host, 2026-10-05, Penpot 2.18.2 through Orca's embedded Windows Chromium:
  all three viewport imports converted 29 boards (the six containers plus the
  23 boxes inside them), kept five fixed, and reverted none. For the 38
  non-text layers, position and size matched the browser within 1 px, except
  the page's `main` wrapper and the unconverted `#card-text` group, whose group
  bounds follow the substituted font and are identical in a snapshot import.
  The import used 81 shapes against 110 for the snapshot, because a board
  replaces each group-plus-backdrop pair.
  - **Resizing and editing** (tablet): widening a space-between row from 300 to
    360 px moved the second and third boxes from 110/221 to 140/281; resizing a
    child from 60 to 100 px shifted its following sibling by 40; making a column
    child taller shifted the siblings below it; a layer appended to a row
    flowed to the end after the gap; editing the card's text to a longer string
    grew the text and its group and the card kept its layout.
  - **Undo, redo, reload** (tablet): one Undo removed all 81 shapes and every
    layout (81 to 1); one Redo restored 81 shapes and 29 layouts; after a saved
    reload there were still 81 shapes and 29 layouts, with the same geometry.
  - Hosts substitute Inter for `DejaVu Sans`, so text widths differ slightly;
    box geometry does not depend on the font.

Observations from the host used to design this, recorded with the
`flex-probe` and `flex-edit-probe` harness actions:

- A layout is applied asynchronously, within about 100 ms of configuration, and
  the first layout on a newly opened page was not applied at all in two runs;
  this is why the host check exists.
- The first appended child is first in a row or column; `board.children` lists
  them in the opposite order.
- Removing a layout leaves children where it last placed them, so a revert
  must restore the captured offsets.
- An absolute child (`layoutChild.absolute`) keeps its position and is excluded
  from the flow. A `fill` child sizing grows to the remaining space; this is
  available for later `flex-grow` support.

## Limits

- Fixed sizing only: a converted board does not hug its content, so editing
  text that grows past its container does not resize the container.
- The native layouts reflow with the host's fonts; the reflow is real
  behavior, not a defect.
- Containers are not converted when the model cannot reproduce them; there is no
  partial conversion of a container.

export const PROTOCOL_VERSION = 1 as const;

export type ScriptPolicy = "off" | "trusted";
export type Severity = "info" | "warning" | "error";
export type SceneKind = "container" | "box" | "text" | "image" | "svg" | "fallback";
export type LayoutKind = "none" | "flex" | "grid";

export interface ViewportSpec {
  id: string;
  name: string;
  width: number;
  height: number;
}

export const DEFAULT_VIEWPORTS: ViewportSpec[] = [
  { id: "desktop", name: "Desktop", width: 1440, height: 900 },
  { id: "tablet", name: "Tablet", width: 768, height: 1024 },
  { id: "mobile", name: "Mobile", width: 390, height: 844 }
];

export interface CaptureRequest {
  protocolVersion: typeof PROTOCOL_VERSION;
  html: string;
  baseUrl?: string;
  viewports: ViewportSpec[];
  scriptPolicy: ScriptPolicy;
  settleDelayMs: number;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface SceneBorder {
  color: string;
  width: number;
  style: string;
}

export interface SceneBorders {
  top: SceneBorder;
  right: SceneBorder;
  bottom: SceneBorder;
  left: SceneBorder;
}

export interface ScenePaint {
  backgroundColor?: string;
  backgroundImage?: string;
  /** Computed CSS background placement retained for asset materialization and diagnostics. */
  backgroundRepeat?: string;
  backgroundRepeatX?: string;
  backgroundRepeatY?: string;
  backgroundSize?: string;
  backgroundPosition?: string;
  backgroundPositionX?: string;
  backgroundPositionY?: string;
  color?: string;
  borderColor?: string;
  borderWidth?: number;
  borderStyle?: string;
  /** All computed sides when their color, width, or style differs. Uniform
   * borders keep the legacy borderColor/borderWidth/borderStyle fields. */
  borders?: SceneBorders;
  radius?: [number, number, number, number];
  opacity?: number;
  boxShadow?: string;
  /** Effective clipping, set only when both axes clip; Penpot containers cannot clip one axis alone. */
  overflow?: "visible" | "hidden" | "clip";
  /** Computed per-axis CSS overflow, retained so single-axis clipping can be diagnosed rather than guessed at. */
  overflowX?: string;
  overflowY?: string;
}

export interface TextStyle {
  fontFamily: string;
  fontSize: number;
  fontWeight: number;
  fontStyle: string;
  /** Unitless line-height multiplier used by Penpot (for example, 1.35). */
  lineHeight: number;
  letterSpacing: number;
  textAlign: string;
  textDecoration: string;
  textTransform: string;
}

export interface SceneLayout {
  kind: LayoutKind;
  direction?: "row" | "row-reverse" | "column" | "column-reverse";
  wrap?: "wrap" | "nowrap";
  justifyContent?: string;
  alignItems?: string;
  rowGap?: number;
  columnGap?: number;
  padding?: [number, number, number, number];
  absolute?: boolean;
  /** True when CSS position is not static. Positioned elements with an
   * automatic or zero z-index paint above non-positioned in-flow content. */
  positioned?: boolean;
}

export interface AssetRef {
  id: string;
  url?: string;
  dataUrl?: string;
  mimeType?: string;
  width?: number;
  height?: number;
}

export interface SceneImagePositionAxis {
  /** Fraction of the space remaining after sizing the image; 0.5 centers it.
   * CSS positions outside the 0..1 interval are valid. */
  percentage: number;
  /** Additional offset in captured page pixels, after any uniform transform. */
  offset: number;
}

export interface SceneImageFit {
  fit: "fill" | "contain" | "cover" | "none" | "scale-down";
  position: { x: SceneImagePositionAxis; y: SceneImagePositionAxis };
  /** Browser natural dimensions in CSS pixels, including srcset density
   * correction. These remain unchanged by CSS transforms. */
  intrinsicWidth: number;
  intrinsicHeight: number;
  /** Uniform CSS transform scale. Defaults to 1 for older scene producers. */
  scale?: number;
}

export interface SceneNode {
  id: string;
  parentId?: string;
  children: string[];
  kind: SceneKind;
  name: string;
  source: string;
  /** Captured box in page pixels. For a transformed layer this is the layer's
   * own (scaled) size plus the position of its top-left corner after every
   * CSS transform; see `rotation`. */
  rect: Rect;
  /** Clockwise rotation in degrees (the CSS convention) about the top-left
   * corner of `rect`. Absent when no transform rotates the layer. */
  rotation?: number;
  /** Effective integer z-index. `z-index: auto` is stored as 0 (its paint
   * position for positioned elements) with `zIndexAuto` set, so explicit
   * numeric zero stays distinct from automatic stacking. */
  zIndex: number;
  /** True when the computed CSS z-index is `auto` rather than numeric. */
  zIndexAuto?: boolean;
  paint: ScenePaint;
  layout: SceneLayout;
  text?: string;
  /** Keep a captured source line on one line when imported. */
  textNoWrap?: boolean;
  /** Horizontal fit scale for a captured line that exceeds its source bounds. */
  textFitScale?: number;
  /** Right-edge space available to a non-wrapping captured text line. */
  textMaxWidth?: number;
  textStyle?: TextStyle;
  assetId?: string;
  /** Replaced image sizing inside the content box (border and padding excluded).
   * Absent for legacy scenes or images without usable natural dimensions. */
  image?: SceneImageFit;
  fallbackReason?: string;
}

export interface Diagnostic {
  severity: Severity;
  code: string;
