215	  const outer = flow.map((child, index) => {
216	    const [mt, mr, mb, ml] = margins[index];
217	    return row ? { main: ml + child.rect.width + mr, cross: mt + child.rect.height + mb } : { main: mt + child.rect.height + mb, cross: ml + child.rect.width + mr };
