      let result: unknown;
      let saves = 0;
      saveListener = penpot.on("contentsave", () => { saves += 1; send({ type: "save-observed", pageId: page.id, saves, result }); });
      const started = profileNow();
      let metrics: ImportMetrics | undefined;
      const diagnostics: unknown[] = [];
